import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "@playwright/test";

// Core-flow smoke test (#72) against the local mock-mode stack started by playwright.config.ts.
// Synthetic text only; the staff token is test-only, generated by scripts/e2e_api.sh for this run.
// The API de-duplicates identical text, so each run (browser, retry) adds a letters-only synthetic suffix.
const routine = () =>
  `I have had a sore throat and a mild fever for two days. Note ${Math.random().toString(36).slice(2, 10).replace(/[0-9]/g, "q")}.`;

test.describe.configure({ mode: "serial" });

test("landing → routine intake → outcome", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("main")).toBeVisible();
  await page.getByRole("navigation", { name: "Demo sections" }).getByRole("link", { name: "Patient intake" }).click();

  await expect(page.getByRole("heading", { name: "Pre-visit symptom intake" })).toBeVisible();
  await page.getByLabel(/Your symptoms/).fill(routine());
  await page.getByRole("checkbox", { name: /I consent/ }).check();
  await page.getByRole("button", { name: "Submit intake" }).click();

  await expect(page.getByRole("heading", { name: "Pre-visit report" })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByRole("region", { name: "Your intake has been received" })).toBeVisible();
  await expect(page.locator('[data-status="submitted"]').first()).toBeVisible();
});

test("staff sign-in → queue → detail → FHIR preview", async ({ page }) => {
  const token = readFileSync(join(__dirname, ".auth", "staff-token"), "utf8").trim();

  await page.goto("/staff");
  await expect(page.getByRole("heading", { name: "Staff sign-in" })).toBeVisible();
  await page.getByLabel("Access token").fill(token);
  await page.getByRole("button", { name: "Sign in" }).click();

  await expect(page.getByRole("button", { name: "Sign out" })).toBeVisible();
  await page.getByRole("button", { name: /^All/ }).click();
  await page.getByRole("button", { name: /^Open intake / }).first().click();
  await expect(page.getByRole("heading", { name: /^Intake / })).toBeVisible();

  await page.getByRole("button", { name: "Load FHIR export" }).click();
  await expect(page.getByTestId("fhir-preview")).toContainText('"resourceType": "Bundle"');
});

test("unknown route renders the styled 404 page", async ({ page }) => {
  const response = await page.goto("/does-not-exist");
  expect(response?.status()).toBe(404);
  await expect(page.getByRole("heading", { level: 1, name: "Page not found" })).toBeVisible();
  await expect(page.getByRole("link", { name: "Return to the dashboard" })).toBeVisible();
});
